INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7513951, 1199998, 101256, '<td valign="top">There is painting titled "Windows Open Simultaneously" by Robert Delaunay that this is very similar to.  Excellent use of color and perspective with lots of intriguing detail - very well done - great captur<br/>e.</td>', 'There is painting titled "Windows Open Simultaneously" by Robert Delaunay that this is very similar to.  Excellent use of color and perspective with lots of intriguing detail - very well done - great capture.', '2017-05-15 20:44:30.000000', NULL, 1),
(7513952, 1199923, 101256, '<td valign="top">Interesting perspective on the outdoors. It might have worked a little better if both figures were visible.  Very nice candid.</td>', 'Interesting perspective on the outdoors. It might have worked a little better if both figures were visible.  Very nice candid.', '2017-05-15 20:45:38.000000', NULL, 1),
(7513953, 1199906, 101256, '<td valign="top">I really like to concept of three separate images done at one time - almost a diptych only in triplicate. Really nice capture, good framing, use of color and detail - very well done.</td>', 'I really like to concept of three separate images done at one time - almost a diptych only in triplicate. Really nice capture, good framing, use of color and detail - very well done.', '2017-05-15 20:47:45.000000', NULL, 1),
(7513954, 1199781, 101256, '<td valign="top">Not exactly sure what this represents.</td>', 'Not exactly sure what this represents.', '2017-05-15 20:49:26.000000', NULL, 1),
(7513955, 1199959, 101256, '<td valign="top">The near field speed effect would have been better if there was more detail to balance against the background.</td>', 'The near field speed effect would have been better if there was more detail to balance against the background.', '2017-05-15 20:50:22.000000', NULL, 1),
(7513956, 1199890, 101256, '<td valign="top">A very antique feel to this - the screen adds some mystery and intrigue to the image.</td>', 'A very antique feel to this - the screen adds some mystery and intrigue to the image.', '2017-05-15 20:51:21.000000', NULL, 1),
(7513957, 1199986, 101256, '<td valign="top">I love candid photography and this is a good one - good color control, like the light to dark transition and the general feeling of good times.</td>', 'I love candid photography and this is a good one - good color control, like the light to dark transition and the general feeling of good times.', '2017-05-15 20:52:10.000000', NULL, 1),
(7513958, 1199927, 101256, '<td valign="top">A different windows-through-windows themed image. Very nicely captured. I feel the image is a little darker than it should be.</td>', 'A different windows-through-windows themed image. Very nicely captured. I feel the image is a little darker than it should be.', '2017-05-15 20:53:19.000000', NULL, 1),
(7513959, 1199984, 101256, '<td valign="top">An air of mystery - I think this might have worked a little better as a black and white image with a little better contrast, but that would make it a different photo. Nicely capture.</td>', 'An air of mystery - I think this might have worked a little better as a black and white image with a little better contrast, but that would make it a different photo. Nicely capture.', '2017-05-15 20:54:32.000000', NULL, 1),
(7513960, 1199726, 101256, '<td valign="top">Like the framing and overall candid feel of this image.</td>', 'Like the framing and overall candid feel of this image.', '2017-05-15 20:55:12.000000', NULL, 1),
(7513961, 1199983, 101256, '<td valign="top">This almost looks like a stock vacation ad photo- the washed out sky doesn''t help it any though.</td>', 'This almost looks like a stock vacation ad photo- the washed out sky doesn''t help it any though.', '2017-05-15 20:56:06.000000', NULL, 1),
(7513962, 1199962, 101256, '<td valign="top">Earth Day at the Apple store - interesting.</td>', 'Earth Day at the Apple store - interesting.', '2017-05-15 20:58:15.000000', NULL, 1),
(7513963, 1199949, 101256, '<td valign="top">This strikes me as something special for some reason, but I can''t really explain it. There is a sense of "deep history" here which just captures my imagination.</td>', 'This strikes me as something special for some reason, but I can''t really explain it. There is a sense of "deep history" here which just captures my imagination.', '2017-05-15 20:59:50.000000', NULL, 1),
(7513964, 1199942, 101256, '<td valign="top">Excellent composition - framing, depth, visual impact all nearly perfect. Well done.</td>', 'Excellent composition - framing, depth, visual impact all nearly perfect. Well done.', '2017-05-15 21:01:14.000000', NULL, 1),
(7513966, 1199911, 101256, '<td valign="top">A little different exposure and contrast control would have made this a much better image.</td>', 'A little different exposure and contrast control would have made this a much better image.', '2017-05-15 21:04:29.000000', NULL, 1),
(7513967, 1199989, 101256, '<td valign="top">A great capture in difficult circumstances.  You actually get a sense of height and altitude when viewing this which frankly surprised me. Well done.</td>', 'A great capture in difficult circumstances.  You actually get a sense of height and altitude when viewing this which frankly surprised me. Well done.', '2017-05-15 21:06:04.000000', NULL, 1),
(7513968, 1200009, 101256, '<td valign="top">A great sense of whimsy, humor and who doesn''t like Pee Wee Herman. And a bicycle chain ring?  Love it - great and fun capture.</td>', 'A great sense of whimsy, humor and who doesn''t like Pee Wee Herman. And a bicycle chain ring?  Love it - great and fun capture.', '2017-05-15 21:07:05.000000', NULL, 1),
(7513969, 1199939, 101256, '<td valign="top">Awesome - simple awesome capture. Very good eye bringing the decay to the fore but in a way that presents it as not a bad thing, but the end of a cycle. Great story behind that window - excellent.</td>', 'Awesome - simple awesome capture. Very good eye bringing the decay to the fore but in a way that presents it as not a bad thing, but the end of a cycle. Great story behind that window - excellent.', '2017-05-15 21:08:08.000000', NULL, 1),
(7513970, 1199849, 101256, '<td valign="top">One of the problems with images like this is that the eye is drawn to a different part of the image than intended. The over exposed window takes away from the subject and you almost have to hunt for the subject.</td>', 'One of the problems with images like this is that the eye is drawn to a different part of the image than intended. The over exposed window takes away from the subject and you almost have to hunt for the subject.', '2017-05-15 21:09:26.000000', NULL, 1),
(7513971, 1199902, 101256, '<td valign="top">There''s an interesting effect here - the screen door gives a feeling that the viewer is looking into another dimension. Really effective.</td>', 'There''s an interesting effect here - the screen door gives a feeling that the viewer is looking into another dimension. Really effective.', '2017-05-15 21:13:08.000000', NULL, 1),
(7513972, 1199836, 101256, '<td valign="top">This is just a personal comment - I think the blue is way overdone - a little less blue on the cityscape would have improved this tremendously.</td>', 'This is just a personal comment - I think the blue is way overdone - a little less blue on the cityscape would have improved this tremendously.', '2017-05-15 21:14:14.000000', NULL, 1),
(7513973, 1199903, 101256, '<td valign="top">Another great capture with the feeling of a stock advertising photo. Stock photos are nothing to laugh at - they have to have impact or they aren''t doing what was intended.  Very nice.</td>', 'Another great capture with the feeling of a stock advertising photo. Stock photos are nothing to laugh at - they have to have impact or they aren''t doing what was intended.  Very nice.', '2017-05-15 21:15:40.000000', NULL, 1),
(7513974, 1199953, 101256, '<td valign="top">A different perspective with low light. The image is a little less crisp that it could be, perhaps a little more time with focus and aperture would have helped.</td>', 'A different perspective with low light. The image is a little less crisp that it could be, perhaps a little more time with focus and aperture would have helped.', '2017-05-15 21:19:21.000000', NULL, 1),
(7513975, 1199924, 101256, '<td valign="top">I just love these candid photos.  I took my Grandson to an Aquarium once and just spent the time taking photos of him interacting with the exhibits. Wonderful.</td>', 'I just love these candid photos.  I took my Grandson to an Aquarium once and just spent the time taking photos of him interacting with the exhibits. Wonderful.', '2017-05-15 21:20:43.000000', NULL, 1),
(7513976, 1199625, 101256, '<td valign="top">Every once in a while you run across an image that would have worked in B&amp;W or color. This is one of them. Great capture - nicely framed and executed. Well done.</td>', 'Every once in a while you run across an image that would have worked in B&W or color. This is one of them. Great capture - nicely framed and executed. Well done.', '2017-05-15 21:21:50.000000', NULL, 1),
(7513977, 1199975, 101256, '<td valign="top">I''ll admit I''m not at all sure what this is - or what the perspective is. It almost seems like a series of layers added on a black canvas. I''ll admit it- I''m stumped.</td>', 'I''ll admit I''m not at all sure what this is - or what the perspective is. It almost seems like a series of layers added on a black canvas. I''ll admit it- I''m stumped.', '2017-05-15 21:24:10.000000', NULL, 1),
(7513978, 1199623, 101256, '<td valign="top">Very artistic - clever in fact. Very well done.</td>', 'Very artistic - clever in fact. Very well done.', '2017-05-15 21:24:47.000000', NULL, 1),
(7513979, 1199865, 101256, '<td valign="top">Certainly a different look at the challenge criteria. like the color combinations and different angular perspectives.</td>', 'Certainly a different look at the challenge criteria. like the color combinations and different angular perspectives.', '2017-05-15 21:25:46.000000', NULL, 1),
(7513980, 1200006, 101256, '<td valign="top">A little more contract control with the background window would have improved this tremendously.</td>', 'A little more contract control with the background window would have improved this tremendously.', '2017-05-15 21:26:36.000000', NULL, 1),
(7513981, 1199955, 101256, '<td valign="top">The true measure of "art" is that it can be interpreted in different ways. Confrontation, Friends, situational - there is a lot here to think and wonder about. Nice capture.</td>', 'The true measure of "art" is that it can be interpreted in different ways. Confrontation, Friends, situational - there is a lot here to think and wonder about. Nice capture.', '2017-05-15 21:28:53.000000', NULL, 1),
(7513982, 1199414, 101256, '<td valign="top">An engaging vista from a different perspective - very nice.</td>', 'An engaging vista from a different perspective - very nice.', '2017-05-15 21:29:30.000000', NULL, 1),
(7513983, 1199848, 101256, '<td valign="top">Absolutely believe that this is, or at least should be, the category winner. This is just too perfect. Well done.</td>', 'Absolutely believe that this is, or at least should be, the category winner. This is just too perfect. Well done.', '2017-05-15 21:30:30.000000', NULL, 1),
