(7513985, 1199714, 101256, '<td valign="top">Wonderful - simply gorgeous antique feel to this. Very well done.</td>', 'Wonderful - simply gorgeous antique feel to this. Very well done.', '2017-05-15 21:31:56.000000', NULL, 1),
(7513986, 1199749, 101256, '<td valign="top">A nice capture from a different perspective.</td>', 'A nice capture from a different perspective.', '2017-05-15 21:32:28.000000', NULL, 1),
(7513987, 1199996, 101256, '<td valign="top">I very much like the way this slides the eye from the right to the left. Different way of viewing the subject not normally seen.</td>', 'I very much like the way this slides the eye from the right to the left. Different way of viewing the subject not normally seen.', '2017-05-15 21:33:13.000000', NULL, 1),
