(7515000, 1199836, 28742, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Challenge Description:</b></div><hr/><i>The window glass or frame must be included in the photo to make it obvious it''s been taken from a window.</i></td></tr></table> <br/><img alt="'' . substr(''//www.artroflmao.com/dpc/DNMC-police.png'', strrpos(''//www.artroflmao.com/dpc/DNMC-police.png'', ''/'') + 1) . ''" border="0" src="//www.artroflmao.com/dpc/DNMC-police.png"/> <br/>Sorry I''m late.</td>', 'Originally posted by Challenge Description:The window glass or frame must be included in the photo to make it obvious it''s been taken from a window.  Sorry I''m late.', '2017-05-22 05:44:49.000000', NULL, 0),
(7515023, 1199906, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that meets the challenge well<br/> <br/>A great image Marcel. I like your exposure that concentrates on the view through the window, what a great view. The inclusion of your colleague as a silhouette really completes the image making it work well. The composition is good but I think it would improve it to exclude the building on the left and perhaps crop the right to match the left.</td>', 'Hello from the critique club An appealing image that meets the challenge well A great image Marcel. I like your exposure that concentrates on the view through the window, what a great view. The inclusion of your colleague as a silhouette really completes the image making it work well. The composition is good but I think it would improve it to exclude the building on the left and perhaps crop the right to match the left.', '2017-05-22 09:45:25.000000', NULL, 0),
